var r=class{static getZonedDate(e){let t=e.getTime();return t-=e.getTimezoneOffset()*60*1e3,new Date(t)}static getMonthName(e){switch(e){case 1:return"JAN";case 2:return"FEB";case 3:return"MAR";case 4:return"APR";case 5:return"MAY";case 6:return"JUN";case 7:return"JUL";case 8:return"AUG";case 9:return"SEP";case 10:return"OCT";case 11:return"NOV";case 12:return"DEC";default:return""}}static getStringTimestamp(){let e=new Date,t=g=>g.toString().padStart(2,"0"),n=e.getFullYear(),s=t(e.getMonth()+1),c=t(e.getDate()),a=t(e.getHours()),u=t(e.getMinutes()),o=t(e.getSeconds());return`${n}-${s}-${c}_${a}-${u}-${o}`}};export{r as a};
